/* the Mirage, from a downloaded model (Dassault Mirage 2000-C, only its shape kept: the gear removed, our own paint - see 11_air.js), cut in
   parts: the body, the right outer wing the missile tears away, the canopy glass, the cockpit, the belly tank. Positions 16-bit over the box, normals 8-bit */
const JET_DATA = {"box":[-7.2988,-1.6658,-4.8493,8.7013,3.3192,4.8385],"parts":{"body":{"n":45282,"p":"","q":""},"wingR":{"n":1656,"p":"","q":""},"glass":{"n":1338,"p":"","q":""},"pit":{"n":1356,"p":"","q":""},"tank":{"n":3012,"p":"","q":""}}};
/* decoding the parts, once */
const JET = { parts: null, mats: {} };
function jetParts() {
  if (JET.parts) return JET.parts; const D = JET_DATA, b = D.box, out = {};
  for (const [k, v] of Object.entries(D.parts)) {
    const pb = Uint8Array.from(atob(v.p), (c) => c.charCodeAt(0)), qb = Uint8Array.from(atob(v.q), (c) => c.charCodeAt(0)), pi = new Int16Array(pb.buffer), qi = new Int8Array(qb.buffer), n = v.n;
    const pos = new Float32Array(n * 3), nrm = new Float32Array(n * 3);
    for (let i = 0; i < n * 3; i++) { const a = i % 3; pos[i] = b[a] + (pi[i] + 32768) / 65535 * (b[a + 3] - b[a]); nrm[i] = qi[i] / 127; }
    const g = new THREE.BufferGeometry(); g.setAttribute('position', new THREE.BufferAttribute(pos, 3)); g.setAttribute('normal', new THREE.BufferAttribute(nrm, 3)); g.computeBoundingSphere(); out[k] = g;
  }
  { const p = out.wingR.attributes.position.array; let s = 0; for (let i = 1; i < p.length; i += 3) s += p[i]; out.wingY = s / (p.length / 3); }
  return (JET.parts = out);
}
/* the paint, worked out on the plane's own shape (no picture to load, and the markings stay where they belong on a wing torn away):
   'il' - the IAF's Mirage of 1973: the desert scheme of sand, brown and green over the top and sides, pale blue-grey below, the radome a
   dark olive; the Star of David roundels on both wings, above and below, and on the fuselage sides; the yellow identification triangles
   with their black border on the upper wings (from the war); 'eg' - an Egyptian fighter in bare metal, its panels a shade apart, the red,
   white and black roundels, the flag across the fin. Both: fine panel lines, grime, soot at the nozzle */
const JET_PAINT = `
float jh3(vec3 p){ return fract(sin(dot(p, vec3(127.1, 311.7, 74.7))) * 43758.5453); }
float jvn(vec3 p){ vec3 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(mix(jh3(i), jh3(i + vec3(1,0,0)), f.x), mix(jh3(i + vec3(0,1,0)), jh3(i + vec3(1,1,0)), f.x), f.y), mix(mix(jh3(i + vec3(0,0,1)), jh3(i + vec3(1,0,1)), f.x), mix(jh3(i + vec3(0,1,1)), jh3(i + vec3(1,1,1)), f.x), f.y), f.z); }
float jfbm(vec3 p){ return jvn(p) * 0.55 + jvn(p * 2.07) * 0.28 + jvn(p * 4.3) * 0.17; }
float jtri(vec2 p, float r){ const float k = 1.7320508; p.x = abs(p.x) - r; p.y = p.y + r / k; if (p.x + k * p.y > 0.0) p = vec2(p.x - k * p.y, -k * p.x - p.y) / 2.0; p.x -= clamp(p.x, -2.0 * r, 0.0); return -length(p) * sign(p.y); }
vec4 jStar(vec2 q, float R){ float d = length(q); if (d > R) return vec4(0.0); float r = R * 0.62, w = R * 0.075;
  float s = min(abs(jtri(q, r)), abs(jtri(vec2(q.x, -q.y), r))); return s < w ? vec4(0.10, 0.22, 0.62, 1.0) : vec4(0.92, 0.92, 0.88, 1.0); }
vec4 jEgy(vec2 q, float R){ float d = length(q) / R; if (d > 1.0) return vec4(0.0); return d < 0.34 ? vec4(0.06, 0.06, 0.06, 1.0) : d < 0.67 ? vec4(0.92, 0.92, 0.9, 1.0) : vec4(0.72, 0.1, 0.1, 1.0); }
vec4 jIdTri(vec2 q, float r){ float d = jtri(q, r); return d < 0.0 ? (d > -r * 0.12 ? vec4(0.05, 0.05, 0.05, 1.0) : vec4(0.95, 0.72, 0.12, 1.0)) : vec4(0.0); }
`;
function jetMat(kind) {
  if (JET.mats[kind]) return JET.mats[kind]; const eg = kind === 'eg';
  const m = new THREE.MeshStandardMaterial({ color: 0xffffff, metalness: eg ? 0.3 : 0.12, roughness: eg ? 0.42 : 0.62 });
  m.onBeforeCompile = (sh) => { sh.uniforms.uWingY = { value: jetParts().wingY };
    sh.vertexShader = sh.vertexShader.replace('#include <common>', '#include <common>\nvarying vec3 vOP; varying vec3 vON;').replace('#include <begin_vertex>', '#include <begin_vertex>\nvOP = position; vON = normal;');
    sh.fragmentShader = sh.fragmentShader.replace('#include <common>', '#include <common>\nvarying vec3 vOP; varying vec3 vON; uniform float uWingY;\n' + JET_PAINT).replace('#include <map_fragment>', `#include <map_fragment>
  { vec3 p = vOP, n = normalize(vON); vec3 c;
    float pan = 1.0 - 0.1 * (1.0 - smoothstep(0.0, 0.025, abs(fract(p.x * 0.85) - 0.5) * 2.0 - 0.95)) - 0.07 * (1.0 - smoothstep(0.0, 0.02, abs(fract(p.z * 1.3 + p.y * 1.3) - 0.5) * 2.0 - 0.96));
    ${eg ? `c = vec3(0.70, 0.72, 0.74) * (0.9 + 0.16 * jh3(floor(p * vec3(1.1, 1.6, 1.4))) ) * (0.94 + 0.12 * jfbm(p * 1.7));
    if (p.x > 8.1) c = vec3(0.22, 0.23, 0.22);
    vec4 r = vec4(0.0); if (abs(n.y) > 0.45) { r = jEgy(vec2(p.x + 3.3, p.z - 3.05), 0.62); if (r.a < 0.5) r = jEgy(vec2(p.x + 3.3, p.z + 3.05), 0.62); }
    if (r.a < 0.5 && abs(n.z) > 0.55 && abs(p.z) < 1.2) r = jEgy(vec2(p.x + 0.6, p.y - 0.1), 0.34);
    if (r.a < 0.5 && abs(n.z) > 0.5 && p.y > 1.45 && p.y < 2.5 && p.x > -6.3 && p.x < -4.6) { float f = (p.y - 1.45) / 1.05; r = f > 0.667 ? vec4(0.75, 0.1, 0.1, 1.0) : f > 0.333 ? vec4(0.93, 0.93, 0.9, 1.0) : vec4(0.06, 0.06, 0.06, 1.0); }
    if (r.a > 0.5) c = r.rgb;` : `float cm = jfbm(p * vec3(0.32, 0.45, 0.32) + vec3(3.1, 7.7, 1.3));
    c = cm > 0.56 ? vec3(0.50, 0.37, 0.22) : cm < 0.40 ? vec3(0.37, 0.39, 0.25) : vec3(0.76, 0.65, 0.45);
    float under = smoothstep(-0.15, -0.45, n.y) * (p.y < uWingY + 0.15 ? 1.0 : 0.0); c = mix(c, vec3(0.60, 0.67, 0.71), under);
    if (p.x > 7.3) c = vec3(0.27, 0.27, 0.2);
    c *= 0.93 + 0.12 * jfbm(p * 2.3);
    vec4 r = vec4(0.0); if (abs(n.y) > 0.45) { r = jStar(vec2(p.x + 3.3, p.z - 3.05), 0.72); if (r.a < 0.5) r = jStar(vec2(p.x + 3.3, p.z + 3.05), 0.72);
      if (r.a < 0.5 && n.y > 0.0) { r = jIdTri(vec2(p.z - 1.75, p.x + 1.2), 0.42); if (r.a < 0.5) r = jIdTri(vec2(p.z + 1.75, p.x + 1.2), 0.42); } }
    if (r.a < 0.5 && abs(n.z) > 0.55 && abs(p.z) < 1.2) r = jStar(vec2(p.x + 1.0, p.y - 0.12), 0.42);
    if (r.a > 0.5) c = r.rgb;`}
    if (p.x < -6.55 && abs(p.y) < 0.75 && abs(p.z) < 0.75) c = mix(c, vec3(0.16, 0.15, 0.14), smoothstep(-6.55, -6.85, p.x));   /* the nozzle, burnt dark */
    diffuseColor.rgb = c * pan; }`); };
  m.customProgramCacheKey = () => 'jet' + kind; return (JET.mats[kind] = m);
}
const _jetGlass = () => JET.glass || (JET.glass = new THREE.MeshStandardMaterial({ color: 0x2a3640, metalness: 0.4, roughness: 0.08, transparent: true, opacity: 0.72 }));
const _jetPit = () => JET.pit || (JET.pit = new THREE.MeshStandardMaterial({ color: 0x1e1f1d, roughness: 0.8 }));
/* the whole plane in one geometry, for the fighters that only fly past (the strafing runs, the bombers over the bridge) */
function jetMerged() {
  const J = jetParts(), list = [J.body, J.wingR, J.tank, J.glass], n = list.reduce((a, g) => a + g.attributes.position.count, 0), pos = new Float32Array(n * 3), nrm = new Float32Array(n * 3); let o = 0;
  for (const g of list) { pos.set(g.attributes.position.array, o * 3); nrm.set(g.attributes.normal.array, o * 3); o += g.attributes.position.count; }
  const g = new THREE.BufferGeometry(); g.setAttribute('position', new THREE.BufferAttribute(pos, 3)); g.setAttribute('normal', new THREE.BufferAttribute(nrm, 3)); g.computeBoundingSphere(); return g;
}
MAT.jet = jetMat('eg');   /* the fighters over the battle are Egypt's */
